#include "rpg/pve_visual.hpp"
#include "rpg/battle_presentation.hpp"
#include <iostream>
#include <stdexcept>
using namespace rpg;using namespace rpg::presentation;
void check(bool ok,const char* why){if(!ok){throw std::runtime_error(why);}}
void advance(PveVisualSession& s){for(int i=0;i<220&&!s.finished();++i){const auto v=s.state();if(v.automatic){check(s.step_automatic().accepted(),"enemy action");}else{const auto targets=target_candidates(v,1);check(!targets.empty()&&s.submit(v.revision,1,"ECO-1").accepted(),"player action");}}check(s.finished(),"attempt completed");}
void definitions(){const auto score=score_lab_definition(),survival=survival_lab_definition();check(score.mode==PveMode::ScoreAttack&&score.rules.action_budget->max_actions==12,"explicit scoring window");check(survival.mode==PveMode::Survival&&survival.boss_turn_goal==3&&survival.boss_turn_clock==TickPolicy::NaturalOnly,"explicit boss clock");check(score.loadouts==ritual_lab_definition().loadouts&&survival.loadouts==score.loadouts&&score.rules.combat_model==team_reference_rules().combat_model,"same skills and core");}
void window(){PveVisualSession s(score_lab_definition());advance(s);const auto o=s.observation();check(o.end==PveEnd::WindowClosed&&!o.objective_met&&o.battle.accepted_actions==12,"window is not ritual victory");check(s.receipt()&&s.receipt()->score==o.score&&s.receipt()->score>0&&s.receipt_count()==1,"one score receipt");check(s.state().progress.credits==0&&s.state().progress.completions.empty(),"no generic credits");}
void read_only(){PveVisualSession s(score_lab_definition());advance(s);const auto before=s.observation();const auto receipt=s.receipt();for(int i=0;i<100;++i){static_cast<void>(pve_hud(s.observation()));check(s.receipt()==receipt,"stable receipt");}check(s.observation()==before&&s.receipt_count()==1,"no repeated settlement by read");auto copy=*s.receipt();copy.score=0;check(s.receipt()==receipt,"owned receipt copy");}
void pending(){PveVisualSession s(score_lab_definition());check(!s.receipt()&&s.receipt_count()==0,"no pending receipt");const auto before=s.observation();check(!s.submit(0,2,"ECO-1").accepted()&&s.observation()==before&&s.receipt_count()==0,"rejected passive cannot score");check(s.submit(0,1,"ECO-1").accepted()&&s.observation().score>0&&!s.receipt(),"partial score not consolidated");}
void survival(){PveVisualSession s(survival_lab_definition());advance(s);const auto o=s.observation();check(o.end==PveEnd::SurvivalReached&&o.objective_met&&o.boss_turns==3&&o.battle.phase==Phase::Running,"outer survival result");const auto h=pve_hud(o);check(!h.commands_open&&h.encounter_finished&&s.receipt()&&s.receipt()->survived,"survival receipt and input gate");check(s.step_automatic().error==VisualError::Finished,"no boss action after goal");}
void early_defeat(){auto d=survival_lab_definition();d.roster[0].max_health=1;PveVisualSession s(d);advance(s);check(!s.observation().objective_met&&s.observation().end==PveEnd::TeamDefeated,"early defeat not survival success");check(s.receipt()&&!s.receipt()->survived,"defeat still records score");}
void early_boss(){auto d=survival_lab_definition();d.roster[1].max_health=1;d.roster[1].stats.block=0;PveVisualSession s(d);check(s.submit(0,1,"ECO-1").accepted()&&s.finished(),"early boss defeat");check(!s.observation().objective_met&&s.observation().end==PveEnd::BossDefeated&&s.receipt(),"boss kill is not survival goal");}
void abandon(){PveVisualSession s(score_lab_definition());check(s.submit(0,1,"ECO-1").accepted(),"partial score");s.abandon();const auto before=s.observation();check(s.submit(s.state().revision,1,"ECO-1").error==VisualError::SafetyStop&&!s.receipt()&&s.receipt_count()==0&&s.observation()==before,"abandon no settlement");s.reset();check(s.observation().score==0&&!s.receipt()&&s.state().progress.attempt==2,"fresh score after abandon");}
void retry(){PveVisualSession s(score_lab_definition());advance(s);const auto first=s.receipt();s.reset();check(!s.receipt()&&s.receipt_count()==1,"new attempt not old receipt");advance(s);check(s.receipt_count()==2&&s.receipt()->attempt_id!=first->attempt_id&&s.receipt()->score==first->score,"independent deterministic attempts");}
void move(){PveVisualSession original(score_lab_definition());advance(original);const auto before=original.receipt();PveVisualSession moved(std::move(original));check(moved.receipt()==before&&moved.receipt_count()==1,"moved score ledger stable");}
void tier(){auto d=score_lab_definition();d.tiers={{1,"teste-I"},{1000,"teste-II"}};PveVisualSession s(d);advance(s);check(s.receipt()->reward_tier=="teste-II"&&s.state().progress.credits==0,"tier metadata only");}
void isolation(){PveVisualSession ritual,score(score_lab_definition()),survival(survival_lab_definition());const auto a=ritual.observation(),b=survival.observation();advance(score);check(ritual.observation()==a&&survival.observation()==b&&!ritual.receipt()&&!survival.receipt(),"scoring isolated");}
void identities(){check(pve_lab_definition(PveLabKind::Score).id=="score-lab"&&pve_lab_definition(PveLabKind::Survival).id=="survival-lab","menu factory identity");bool caught=false;try{static_cast<void>(pve_lab_definition(static_cast<PveLabKind>(99)));}catch(const std::invalid_argument&){caught=true;}check(caught,"invalid variant rejected");}
int main(){try{definitions();window();read_only();pending();survival();early_defeat();early_boss();abandon();retry();move();tier();isolation();identities();std::cout<<"REG_SCORED_VISUAL_TESTS_RESULT passed=13 total=13\n";return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}